    @staticmethod
    def _version_tuple(value):
        """Convert a release tag such as v2.3.14 into comparable integers."""
        match = re.search(r"(\d+(?:\.\d+)+)", str(value or ""))
        if not match:
            return ()
        try:
            return tuple(int(part) for part in match.group(1).split("."))
        except ValueError:
            return ()

    def _start_update_check(self):
        # Do not perform network activity while a download is running.
        if self.is_downloading:
            return
        threading.Thread(target=self._check_latest_release, daemon=True, name="GitHubUpdateCheck").start()

    def _check_latest_release(self):
        try:
            response = requests.get(
                GITHUB_LATEST_RELEASE_API,
                headers={"Accept": "application/vnd.github+json", "User-Agent": "YaDiskBackup"},
                timeout=(2.5, 3.5),
            )
            response.raise_for_status()
            release = response.json()
            if release.get("draft") or release.get("prerelease"):
                return
            latest_tag = str(release.get("tag_name", "")).strip()
            latest_version = self._version_tuple(latest_tag)
            current_version = self._version_tuple(APP_VERSION)
            release_url = release.get("html_url") or GITHUB_URL
            if latest_version and current_version and latest_version > current_version:
                self.root.after(0, self._show_update_link, latest_tag.lstrip("vV"), release_url)
        except Exception:
            # Updates are optional: offline, API limits and GitHub errors stay silent.
            return

    def _show_update_link(self, latest_version, release_url):
        if self.is_downloading:
            # Defer the notification until the current download has finished.
            self.root.after(15000, lambda: self._show_update_link(latest_version, release_url))
            return
        self.update_link.configure(text=f"Доступно обновление v.{latest_version}")
        self.update_link.bind("<Button-1>", lambda _event: webbrowser.open(release_url))
        if not self.update_link.winfo_manager():
            self.update_link.pack(side="right", anchor="ne", padx=(8, 0), pady=(0, 2))

