    def _new_page(self, name):
        """Create a real, independent wizard page (no shared Canvas/scroll layer)."""
        page = tk.Frame(self.body, bg=COLORS["bg"])
        page.grid(row=0, column=0, sticky="nsew")
        page.grid_rowconfigure(0, weight=1)
        page.grid_columnconfigure(0, weight=1)
        page.grid_columnconfigure(1, weight=0, minsize=240)

        main = tk.Frame(page, bg=COLORS["bg"])
        main.grid(row=0, column=0, sticky="nsew", padx=(0, 12))
        side = self._card(page)
        side.grid(row=0, column=1, sticky="nsew")
        side.grid_columnconfigure(0, weight=1)
        self.pages[name] = {"page": page, "main": main, "side": side}
        return main, side

    def _on_mousewheel(self, event, canvas=None):
        """Route wheel input to the widget under the pointer.

        The journal owns its own scroll; the rest of the download page scrolls
        as one area, even when the pointer is over a child widget/card.
        """
        try:
            target = self.root.winfo_containing(event.x_root, event.y_root)
        except tk.TclError:
            target = None

        logs = [getattr(self, "log_text", None), getattr(self, "results_log", None)]
        if target is not None:
            widget = target
            while widget is not None:
                if widget in logs and widget is not None:
                    try:
                        if getattr(event, "num", None) == 4:
                            direction = -1
                        elif getattr(event, "num", None) == 5:
                            direction = 1
                        else:
                            direction = -1 if getattr(event, "delta", 0) > 0 else 1
                        widget.yview_scroll(direction, "units")
                    except tk.TclError:
                        pass
                    return "break"
                try:
                    widget = widget.master
                except AttributeError:
                    break

        # Pick the scroll area that contains the pointer; step 3 and the
        # download screen each own an independent canvas.
        results_canvas = getattr(self, "results_canvas", None)
        if results_canvas is not None and target is not None:
            widget = target
            while widget is not None:
                if widget is results_canvas:
                    return self._results_wheel(event)
                try:
                    widget = widget.master
                except AttributeError:
                    break

        for candidate_name in ("step3_content_canvas", "download_content_canvas"):
            candidate = getattr(self, candidate_name, None)
            if target is not None and candidate is not None:
                widget = target
                while widget is not None:
                    if widget is candidate:
                        canvas = candidate
                        break
                    try:
                        widget = widget.master
                    except AttributeError:
                        break
                if canvas is candidate:
                    break
        canvas = canvas or getattr(self, "download_content_canvas", None)
        if canvas is not None:
            try:
                canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            except tk.TclError:
                pass
        return "break"

