    def _link(self, parent, text, url):
        label = tk.Label(parent, text=text, bg=parent.cget("bg"), fg=COLORS["blue"], font=(FONT, 9, "underline"), cursor="hand2")
        label.bind("<Button-1>", lambda _e: webbrowser.open(url))
        label.bind("<Enter>", lambda _e: label.configure(fg=COLORS["accent"]))
        label.bind("<Leave>", lambda _e: label.configure(fg=COLORS["blue"]))
        return label

    def _image(self, key, encoded, max_width=None, max_height=None):
        try:
            img = tk.PhotoImage(data=encoded)
            factor = max(1, (img.width() + max_width - 1) // max_width) if max_width else 1
            if max_height:
                factor = max(factor, (img.height() + max_height - 1) // max_height)
            if factor > 1:
                img = img.subsample(factor, factor)
            self.image_refs[key] = img
            return img
        except tk.TclError:
            return None

