    def _build_step_two(self):
        main, side = self._new_page("step2")
        card = self._card(main)
        card.pack(fill="x", pady=(0, 10))
        self._section_heading(card, "Шаг 2. Получите и вставьте Cookie", "Нам нужен Cookie из вкладки Яндекс.Диска, чтобы сервер не заблокировал скачивание.")

        # Выбор способа получения Cookie. Содержимое каждой вкладки прокручивается
        # отдельно, чтобы шаг помещался в невысокие окна.
        tabs = ttk.Notebook(card, style="Cookie.TNotebook")
        tabs.pack(fill="x", padx=14, pady=(0, 8))
        extension_tab = tk.Frame(tabs, bg=COLORS["surface_alt"])
        devtools_tab = tk.Frame(tabs, bg=COLORS["surface_alt"])
        tabs.add(extension_tab, text="Быстро — через расширение")
        tabs.add(devtools_tab, text="Вручную — через консоль (F12)")
        self.cookie_method_tabs = tabs

        def make_scroll_area(parent, height=285):
            outer = tk.Frame(parent, bg=COLORS["surface_alt"])
            outer.pack(fill="both", expand=True)
            canvas = tk.Canvas(outer, height=height, bg=COLORS["surface_alt"],
                               highlightthickness=0, borderwidth=0)
            scrollbar = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview,
                                      style="Slim.Vertical.TScrollbar")
            canvas.configure(yscrollcommand=scrollbar.set)
            scrollbar.pack(side="right", fill="y")
            canvas.pack(side="left", fill="both", expand=True)
            inner = tk.Frame(canvas, bg=COLORS["surface_alt"], padx=12, pady=10)
            window_id = canvas.create_window((0, 0), window=inner, anchor="nw")
            inner.bind("<Configure>", lambda _e: canvas.configure(scrollregion=canvas.bbox("all")))
            canvas.bind("<Configure>", lambda e: canvas.itemconfigure(window_id, width=e.width))
            def wheel(event):
                if getattr(event, "delta", 0):
                    canvas.yview_scroll(int(-event.delta / 120), "units")
                elif getattr(event, "num", None) == 4:
                    canvas.yview_scroll(-1, "units")
                elif getattr(event, "num", None) == 5:
                    canvas.yview_scroll(1, "units")
                return "break"
            for widget in (canvas, inner):
                widget.bind("<MouseWheel>", wheel, add="+")
                widget.bind("<Button-4>", wheel, add="+")
                widget.bind("<Button-5>", wheel, add="+")
            return inner

        ext_content = make_scroll_area(extension_tab, height=285)
        ext_content.grid_columnconfigure(0, weight=1)
        ext_text = tk.Frame(ext_content, bg=COLORS["surface_alt"])
        ext_text.grid(row=0, column=0, sticky="nsew", padx=(0, 8))
        tk.Label(ext_text, text="1. Установите Cookie-Editor", bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 10, "bold")).pack(anchor="w")
        tk.Label(ext_text, text="Откройте магазин расширений Chrome и нажмите «Установить».", bg=COLORS["surface_alt"], fg=COLORS["muted"], font=(FONT, 9), wraplength=500, justify="left").pack(anchor="w", pady=(4, 7))
        ttk.Button(ext_text, text="🌐  Установить Cookie-Editor", style="Blue.TButton", command=lambda: webbrowser.open(COOKIE_EDITOR_URL)).pack(anchor="w")
        tk.Label(ext_text, text="2. Откройте Яндекс.Диск и нажмите значок расширения Cookie-Editor.", bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 10, "bold"), wraplength=500, justify="left").pack(anchor="w", pady=(10, 0))
        tk.Label(ext_text, text="Нажмите: This site → Разрешить, затем ещё раз нажмите на расширение Cookie-Editor. В выпавшем списке внизу справа выберите Export As → Header String. Вставьте скопированный в буфер текст в поле ниже.", bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 10), wraplength=500, justify="left").pack(anchor="w", pady=(4, 0))
        editor_img = self._image("cookie_editor", COOKIE_EDITOR_PNG, 170, 250)
        if editor_img:
            tk.Label(ext_content, image=editor_img, bg=COLORS["surface_alt"]).grid(row=0, column=1, sticky="ne", padx=(4, 0))

        manual_content = make_scroll_area(devtools_tab, height=285)
        tk.Label(manual_content, text="1. Откройте Яндекс.Диск и нажмите F12 или правой кнопкой мыши выберите «Посмотреть код» / «Режим разработчика».", bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 9), justify="left").pack(anchor="w")
        manual_text = "2. Откройте Network (Сеть) и обновите страницу клавишей F5.\n3. В левой колонке выберите файл с названием страницы или get-dir-size. Нажмите на него.\n4. Справа откройте Headers → Request Headers.\n5. Найдите Cookie (внизу) и скопируйте значение после двоеточия целиком.\n6. Вставьте строку в поле ниже."
        tk.Label(manual_content, text=manual_text, bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 9), justify="left", anchor="w", wraplength=650).pack(anchor="w", pady=(5, 8))
        dev_img = self._image("devtools", DEVTOOLS_PNG, 590, 190)
        if dev_img:
            tk.Label(manual_content, image=dev_img, bg=COLORS["surface_alt"]).pack(anchor="w")

        cookie_label = tk.Frame(card, bg=COLORS["surface"])
        cookie_label.pack(fill="x", padx=16, pady=(0, 4))
        tk.Label(cookie_label, text="3  Вставьте Cookie из выбранного способа", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 10, "bold")).pack(side="left")

        cookie_wrap = tk.Frame(card, bg=COLORS["surface"])
        cookie_wrap.pack(fill="x", padx=16)
        cookie_wrap.grid_columnconfigure(0, weight=1)
        self.cookies_text = tk.Text(cookie_wrap, height=2, wrap="none", font=(MONO, 9), bg=COLORS["input"], fg=COLORS["text"], insertbackground=COLORS["text"], relief="solid", bd=1, highlightthickness=1, highlightbackground=COLORS["border"], highlightcolor=COLORS["blue"], padx=9, pady=6, undo=True, takefocus=True)
        cookie_scroll = ttk.Scrollbar(cookie_wrap, orient="horizontal", command=self.cookies_text.xview, style="Slim.Horizontal.TScrollbar")
        self.cookies_text.configure(xscrollcommand=cookie_scroll.set)
        self.cookies_text.grid(row=0, column=0, sticky="ew")
        cookie_scroll.grid(row=1, column=0, sticky="ew")
        self._enable_paste(self.cookies_text)

        self.cookies_text.bind("<KeyRelease>", lambda _e: (self._refresh_checklist(), self._schedule_autosave(), self._update_step3_footer_action()), add="+")
        for event_name in ("<<Paste>>", "<<Cut>>", "<<Undo>>", "<<Redo>>"):
            self.cookies_text.bind(event_name, lambda _e: (self._schedule_autosave(), self._update_step3_footer_action()), add="+")
        self._build_progress_sidebar(side, active=2)

    def _build_step_three(self):
        main, side = self._new_page("step3")
        # Step 3 scrolls as one continuous work area. The bottom navigation
        # is outside this canvas and therefore stays pinned in place.
        scroll_host = tk.Frame(main, bg=COLORS["bg"])
        scroll_host.pack(fill="both", expand=True)
        canvas = tk.Canvas(scroll_host, bg=COLORS["bg"], highlightthickness=0, bd=0)
        self.step3_content_canvas = canvas
        scrollbar = ttk.Scrollbar(scroll_host, orient="vertical", command=canvas.yview, style="Slim.Vertical.TScrollbar")
        canvas.configure(yscrollcommand=scrollbar.set)
        scrollbar.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        content = tk.Frame(canvas, bg=COLORS["bg"])
        content_window = canvas.create_window((0, 0), window=content, anchor="nw")
        content.bind("<Configure>", lambda _e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>", lambda e: canvas.itemconfigure(content_window, width=e.width))
        main = content
        card = self._card(main)
        card.pack(fill="x", pady=(0, 10))
        self._section_heading(card, "Шаг 3. Выберите папку и запустите скачивание", "Файлы с Яндекс Диска будут сохранены прямо в выбранную папку, без дополнительной папки с названием источника.")
        path_row = tk.Frame(card, bg=COLORS["surface"])
        path_row.pack(fill="x", padx=16, pady=(0, 14))
        path_row.grid_columnconfigure(0, weight=1)
        tk.Label(path_row, text="Куда сохранить файлы (содержимое попадёт прямо сюда)", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 10, "bold")).grid(row=0, column=0, sticky="w", pady=(0, 5), columnspan=2)
        self.path_var = tk.StringVar(value=str(Path.home() / "Downloads" / "Яндекс.Диск"))
        self.path_entry = ttk.Entry(path_row, textvariable=self.path_var, font=(MONO, 9))
        self.path_entry.grid(row=1, column=0, sticky="ew", padx=(0, 8))
        ttk.Button(path_row, text="📁  Выбрать папку", style="Secondary.TButton", command=self.browse_folder).grid(row=1, column=1)
        self.path_var.trace_add("write", lambda *_: (self._refresh_checklist(), self._schedule_autosave(), self._update_step3_footer_action()))
        self._enable_entry_paste(self.path_entry)

        mode_card = self._card(main)
        mode_card.pack(fill="x", pady=(0, 10))
        self._section_heading(mode_card, "Как продолжить скачивание", "Программа помнит, на чём остановилась. Новые папки скачиваются с нуля.")
        self.resume_mode_var = tk.StringVar(value="resume")
        self.resume_mode_var.trace_add("write", lambda *_: self._update_step3_footer_action())
        def add_mode(value, heading, detail):
            row = tk.Frame(mode_card, bg=COLORS["surface"])
            row.pack(fill="x", padx=16, pady=(0, 8), anchor="w")
            radio = tk.Radiobutton(row, variable=self.resume_mode_var, value=value,
                bg=COLORS["surface"], fg=COLORS["text"], activebackground=COLORS["surface"],
                selectcolor=COLORS["surface_alt"], anchor="w", padx=0, pady=0)
            radio.pack(side="left", anchor="n", padx=(0, 7))
            text_box = tk.Frame(row, bg=COLORS["surface"])
            text_box.pack(side="left", fill="x", expand=True)
            heading_label = tk.Label(text_box, text=heading, bg=COLORS["surface"], fg=COLORS["text"],
                     font=(FONT, 9, "bold"), anchor="w", justify="left", cursor="hand2")
            heading_label.pack(anchor="w", fill="x")
            detail_label = tk.Label(text_box, text=detail, bg=COLORS["surface"], fg=COLORS["muted"],
                     font=(FONT, 8), anchor="w", justify="left", wraplength=700, cursor="hand2")
            detail_label.pack(anchor="w", pady=(2, 0), fill="x")
            for label in (heading_label, detail_label, text_box, row):
                label.bind("<Button-1>", lambda _e, control=radio: (control.invoke(), "break")[1])
            return radio
        rb_resume = add_mode("resume", "Продолжить с места остановки (рекомендовано)",
            "Программа сразу перейдёт к оставшимся файлам. То, что скачано в прошлый раз, будет проверено вторым прогоном.")
        rb_start = add_mode("start", "Начать с начала",
            "Программа заново попробует найти и скачать те файлы, которые не удалось загрузить в прошлый раз (дольше).")
        rb_migrate = add_mode("migrate_2314", "Продолжить после обновления с v 2.3.14",
            "Для перехода со старой версии: найдёт последний сохранённый файл и продолжит со следующего. Старый манифест не используется.")
        self._add_tooltip(rb_resume, "Быстрый режим: пропущенные ранее файлы повторно проверяться не будут.")
        self._add_tooltip(rb_start, "Повторно проверяет файлы, которые не удалось загрузить в прошлый раз.")
        self._add_tooltip(rb_migrate, "Миграция с v 2.3.14: ориентируется на существующие локальные файлы и алфавитный обход облака.")
        self.retry_preview_var = tk.BooleanVar(value=True)
        self.retry_preview_var.trace_add("write", lambda *_: self._update_step3_footer_action())
        preview_row = tk.Frame(mode_card, bg=COLORS["surface"])
        preview_row.pack(fill="x", padx=16, pady=(2, 12), anchor="w")
        self.retry_preview_check = tk.Checkbutton(
            preview_row, text="", variable=self.retry_preview_var, bg=COLORS["surface"],
            activebackground=COLORS["surface"], selectcolor=COLORS["surface_alt"], padx=0, pady=0)
        self.retry_preview_check.pack(side="left", anchor="n", padx=(0, 7))
        preview_text = tk.Frame(preview_row, bg=COLORS["surface"])
        preview_text.pack(side="left", fill="x", expand=True)
        preview_heading = tk.Label(preview_text, text="Найти оригиналы для превью", bg=COLORS["surface"], fg=COLORS["text"],
                 font=(FONT, 9, "bold"), anchor="w", cursor="hand2")
        preview_heading.pack(anchor="w")
        preview_detail = tk.Label(preview_text, text="Программа заново проверит скачанные превью. Если Яндекс восстановил к ним доступ, они заменятся на качественные оригиналы.",
                 bg=COLORS["surface"], fg=COLORS["muted"], font=(FONT, 8), anchor="w",
                 justify="left", wraplength=700, cursor="hand2")
        preview_detail.pack(anchor="w", pady=(2, 0))
        for label in (preview_heading, preview_detail, preview_text, preview_row):
            label.bind("<Button-1>", lambda _e: (self.retry_preview_check.invoke(), "break")[1])
        self._add_tooltip(self.retry_preview_check, "Дополнительная проверка превью: если оригиналы снова доступны, заменит ими превью.")

        # Keep these variables for the settings refresh logic, but do not render
        # the redundant "Проверка настроек" card on step 3.
        self.review_urls = tk.StringVar(value="Не добавлены")
        self.review_cookie = tk.StringVar(value="Не указан")
        self.review_path = tk.StringVar(value="")
        self.launch_btn = ttk.Button(self.bottom_left, text="↓  Начать скачивание",
                                     style="Primary.TButton", command=self.start_download_thread)
        self._build_progress_sidebar(side, active=3)

    def _build_results_screen(self):
        main, side = self._new_page("results")
        # Compact results dashboard: main summary/actions + persistent progress sidebar.
        outer = tk.Frame(main, bg=COLORS["bg"])
        outer.pack(fill="both", expand=True)
        self.results_canvas = tk.Canvas(outer, bg=COLORS["bg"], highlightthickness=0, bd=0)
        scroll = ttk.Scrollbar(outer, orient="vertical", command=self.results_canvas.yview, style="Slim.Vertical.TScrollbar")
        self.results_canvas.configure(yscrollcommand=scroll.set)
        scroll.pack(side="right", fill="y")
        self.results_canvas.pack(side="left", fill="both", expand=True)
        content = tk.Frame(self.results_canvas, bg=COLORS["bg"])
        window = self.results_canvas.create_window((0, 0), window=content, anchor="nw")
        content.bind("<Configure>", lambda _e: self.results_canvas.configure(scrollregion=self.results_canvas.bbox("all")))
        self.results_canvas.bind("<Configure>", lambda e: self.results_canvas.itemconfigure(window, width=e.width))

        summary = self._card(content)
        summary.pack(fill="x", pady=(0, 8))
        tk.Label(summary, text="Итоги скачивания", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 15, "bold")).pack(anchor="w", padx=12, pady=(7, 3))
        self.results_total_var = tk.StringVar(value="")
        total = tk.Frame(summary, bg=COLORS["surface_alt"], padx=9, pady=4)
        total.pack(fill="x", padx=9, pady=(0, 5))
        tk.Label(total, textvariable=self.results_total_var, bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 8)).pack(anchor="w")
        stats = tk.Frame(summary, bg=COLORS["surface"])
        stats.pack(fill="x", padx=10, pady=(0, 8))
        self.result_vars = {}
        specs = [
            ("originals", "Оригиналы", "#EAF8F0", "#079447"),
            ("previews", "Превью", "#EAF2FC", COLORS["text"]),
            ("failed", "Не удалось", "#FFF0F0", "#E62E24"),
        ]
        for i, (key, title, tile_bg, value_color) in enumerate(specs):
            tile = tk.Frame(stats, bg=tile_bg, padx=9, pady=5)
            tile.grid(row=i//2, column=i%2, sticky="nsew", padx=3, pady=3)
            stats.grid_columnconfigure(i%2, weight=1, uniform="result_tile")
            tk.Label(tile, text=title, bg=tile_bg, fg=COLORS["text"], font=(FONT, 8, "bold")).pack(anchor="w")
            value = tk.StringVar(value="—")
            self.result_vars[key] = value
            tk.Label(tile, textvariable=value, bg=tile_bg, fg=value_color, font=(FONT, 17, "bold")).pack(anchor="w", pady=(0, 0))
            size = tk.StringVar(value="")
            self.result_vars[key+"_size"] = size
            tk.Label(tile, textvariable=size, bg=tile_bg, fg=COLORS["muted"], font=(FONT, 8)).pack(anchor="w")
            delta = tk.StringVar(value="")
            self.result_vars[key+"_delta"] = delta
            delta_label = tk.Label(tile, textvariable=delta, bg=tile_bg, fg="#079447", font=(FONT, 8))
            delta_label.pack(anchor="w", pady=(2, 0))
            self.result_vars[key+"_delta_label"] = delta_label
        self.results_catalog_delta_var = tk.StringVar(value="")
        tk.Label(summary, textvariable=self.results_catalog_delta_var, bg=COLORS["surface"], fg="#079447", font=(FONT, 8)).pack(anchor="w", padx=12, pady=(0, 5))

        actions = self._card(content)
        actions.pack(fill="x", pady=(0, 8))
        tk.Label(actions, text="Действия с результатами", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 11, "bold")).pack(anchor="w", padx=12, pady=(6, 3))
        row = tk.Frame(actions, bg=COLORS["surface"])
        row.pack(fill="x", padx=10, pady=(0, 6))
        row.grid_columnconfigure((0, 1, 2), weight=1, uniform="result_action")
        ttk.Button(row, text="📁  Открыть папку", style="Success.TButton", command=self.open_download_folder).grid(row=0, column=0, sticky="ew", padx=(0, 5))
        ttk.Button(row, text="▤  Открыть итоговый отчёт", style="Secondary.TButton",
                   command=lambda: self._open_report(getattr(self, "report_path", None))).grid(row=0, column=1, sticky="ew", padx=5)
        ttk.Button(row, text="⚠  Отчёт об ошибках", style="Secondary.TButton",
                   command=lambda: self._open_report(getattr(self, "error_log_path", None))).grid(row=0, column=2, sticky="ew", padx=(5, 0))

        preview_card = self._card(content)
        preview_card.pack(fill="x", pady=(0, 8))
        tk.Label(preview_card, text="Дополнительная проверка", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 11, "bold")).pack(anchor="w", padx=12, pady=(6, 3))
        preview_row = tk.Frame(preview_card, bg=COLORS["surface"])
        preview_row.pack(fill="x", padx=10, pady=(0, 6))
        self.results_preview_btn = ttk.Button(preview_row, text="📥  Попробовать скачать оригиналы", style="Danger.TButton",
                                              command=lambda: self.start_download_thread(preview_only=True))
        self.results_preview_btn.pack(side="left", padx=(0, 12))
        tk.Label(preview_row, text="Повторно проверит файлы, которые скачались только как превью. Если оригинал снова доступен, он заменит превью.",
                 bg=COLORS["surface"], fg=COLORS["muted"], font=(FONT, 8), wraplength=480, justify="left").pack(side="left", fill="x", expand=True)

        # Keep the activity journal available at the end of the results page too.
        results_log_card = self._card(content)
        results_log_card.pack(fill="x", pady=(0, 10))
        results_log_head = tk.Frame(results_log_card, bg=COLORS["surface"])
        results_log_head.pack(fill="x", padx=14, pady=(8, 4))
        tk.Label(results_log_head, text="Журнал действий", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 10, "bold")).pack(side="left")
        ttk.Button(results_log_head, text="Очистить", style="Secondary.TButton", command=self.clear_log).pack(side="right")
        results_log_body = tk.Frame(results_log_card, bg=COLORS["surface"])
        results_log_body.pack(fill="x", padx=12, pady=(0, 8))
        self.results_log = tk.Text(results_log_body, height=6, state="disabled", wrap="word", font=(MONO, 8), bg="#FBFCFD", fg="#344054", relief="solid", bd=1, highlightthickness=1, highlightbackground=COLORS["border"], padx=9, pady=6)
        results_log_scroll = ttk.Scrollbar(results_log_body, orient="vertical", command=self.results_log.yview, style="Slim.Vertical.TScrollbar")
        self.results_log.configure(yscrollcommand=results_log_scroll.set)
        self._configure_log_tags(self.results_log)
        self.results_log.bind("<MouseWheel>", lambda e: self._journal_wheel(e, self.results_log), add="+")
        self.results_log.bind("<Button-4>", lambda e: self._journal_wheel(e, self.results_log), add="+")
        self.results_log.bind("<Button-5>", lambda e: self._journal_wheel(e, self.results_log), add="+")
        self.results_log.pack(side="left", fill="both", expand=True)
        results_log_scroll.pack(side="right", fill="y")
        results_log_handle = tk.Label(results_log_card, text="━━━━  Перетащите, чтобы изменить высоту журнала  ━━━━", bg=COLORS["surface_alt"], fg=COLORS["muted"], cursor="sb_v_double_arrow", font=(FONT, 8), padx=10, pady=4)
        results_log_handle.pack(fill="x", padx=12, pady=(0, 8))
        results_log_handle.bind("<Button-1>", self._log_resize_start)
        results_log_handle.bind("<B1-Motion>", self._log_resize_drag)

        # Match the reference mockup's right-hand progress summary.
        for child in side.winfo_children():
            child.destroy()
        side.grid_columnconfigure(0, weight=1)
        tk.Label(side, text="Ваш прогресс", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 13, "bold")).grid(row=0, column=0, sticky="w", padx=14, pady=(12, 10))
        for idx, title in enumerate(("✓  Ссылка на папку", "✓  Cookie указан", "✓  Скачивание завершено"), start=1):
            tk.Label(side, text=title, bg=COLORS["surface"], fg="#079447", font=(FONT, 9, "bold")).grid(row=idx, column=0, sticky="w", padx=14, pady=(0, 10))
        ttk.Separator(side).grid(row=4, column=0, sticky="ew", padx=14, pady=(0, 8))
        self.result_side_time = tk.StringVar(value="Время работы: 0 сек.")
        box = tk.Frame(side, bg=COLORS["surface_alt"], padx=9, pady=7)
        box.grid(row=5, column=0, sticky="ew", padx=10, pady=(0, 7))
        tk.Label(box, text="Время", bg=COLORS["surface_alt"], fg=COLORS["muted"], font=(FONT, 8)).pack(anchor="w")
        tk.Label(box, textvariable=self.result_side_time, bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 10, "bold"), wraplength=190, justify="left").pack(anchor="w", pady=(3, 0))

    def _results_wheel(self, event):
        if getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            delta = -1 if getattr(event, "delta", 0) > 0 else 1
        self.results_canvas.yview_scroll(delta * 3, "units")
        return "break"

    def _journal_wheel(self, event, widget):
        """Scroll only the journal under the pointer; never bubble to page canvas."""
        if getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            delta = -1 if getattr(event, "delta", 0) > 0 else 1
        try:
            widget.yview_scroll(delta, "units")
        except tk.TclError:
            pass
        return "break"

    def _refresh_results_screen(self):
        stats = getattr(self, "final_stats", {}) or {}
        counts = stats.get("counts", {})
        sizes = stats.get("sizes", {})
        total = stats.get("total", 0)
        originals_total = max(0, int(total or 0))
        originals_count = max(0, int(counts.get("originals", 0) or 0))
        previews_total = max(0, originals_total - originals_count)
        previous = getattr(self, "previous_run_summary", None) or {}
        previous_counts = previous.get("counts", {}) if isinstance(previous, dict) else {}
        previous_sizes = previous.get("sizes", {}) if isinstance(previous, dict) else {}
        for key in ("originals", "previews", "failed"):
            count = max(0, int(counts.get(key, 0) or 0))
            if key == "originals":
                denominator = originals_total
                self.result_vars[key].set(f"{count:,} / {denominator:,}".replace(",", " "))
            elif key == "previews":
                denominator = previews_total
                self.result_vars[key].set(f"{count:,} / {denominator:,}".replace(",", " "))
            else:
                self.result_vars[key].set(f"{count:,}".replace(",", " "))
            self.result_vars[key+"_size"].set(self._human_size(sizes.get(key, 0)) if sizes.get(key, 0) else "")
            delta_var = self.result_vars.get(key+"_delta")
            delta_label = self.result_vars.get(key+"_delta_label")
            if previous_counts and key in previous_counts:
                delta_count = count - int(previous_counts.get(key, 0) or 0)
                delta_size = int(sizes.get(key, 0) or 0) - int(previous_sizes.get(key, 0) or 0)
                sign_count = "+" if delta_count > 0 else "−" if delta_count < 0 else "±"
                sign_size = "+" if delta_size > 0 else "−" if delta_size < 0 else "±"
                delta_text = f"{sign_count}{abs(delta_count):,} файлов · {sign_size}{self._human_size(abs(delta_size))}".replace(",", " ")
                # Favorable changes are green: more originals/previews, fewer failures.
                favorable = (delta_count >= 0 if key in ("originals", "previews") else delta_count <= 0)
                delta_color = "#079447" if favorable else "#E62E24"
                if delta_count == 0 and delta_size == 0:
                    delta_text = "Без изменений к прошлому запуску"
                delta_var.set(delta_text)
                if delta_label is not None:
                    delta_label.configure(fg=delta_color)
            else:
                delta_var.set("Сравнение появится со следующего запуска")
                if delta_label is not None:
                    delta_label.configure(fg=COLORS["muted"])
        self.results_total_var.set(f"Всего найдено файлов: {total:,}".replace(",", " ") +
                                   f"   •   Общий размер по данным Яндекс.Диска: {stats.get('size', '—')}")
        catalog_delta = getattr(self, "current_catalog_delta", None)
        if catalog_delta and catalog_delta.get("previous"):
            count_delta = int(catalog_delta.get("count", 0)) - int(catalog_delta["previous"].get("count", 0))
            size_delta = int(catalog_delta.get("size", 0)) - int(catalog_delta["previous"].get("size", 0))
            sign_count = "+" if count_delta > 0 else "−" if count_delta < 0 else "±"
            sign_size = "+" if size_delta > 0 else "−" if size_delta < 0 else "±"
            self.results_catalog_delta_var.set(f"К прошлому сканированию Яндекс.Диска: {sign_count}{abs(count_delta):,} файлов · {sign_size}{self._human_size(abs(size_delta))}".replace(",", " "))
            self.results_catalog_delta_var.configure(fg="#079447" if count_delta >= 0 and size_delta >= 0 else ("#E62E24" if count_delta < 0 or size_delta < 0 else "#079447"))
        else:
            self.results_catalog_delta_var.set("Сравнение каталога появится после следующего сканирования")
            self.results_catalog_delta_var.configure(fg=COLORS["muted"])
        try:
            elapsed = max(0, int(round(time.time() - getattr(self, "run_started_at", time.time()))))
            self.result_side_time.set(f"Время работы: {elapsed} сек.")
        except (tk.TclError, AttributeError):
            pass
        if hasattr(self, "log_text") and hasattr(self, "results_log"):
            try:
                if not getattr(self, "_results_log_seeded", False):
                    if self.results_log.get("1.0", "end-1c").strip() == "":
                        self.results_log.configure(state="normal")
                        self.results_log.insert("1.0", self.log_text.get("1.0", "end-1c"))
                        self.results_log.configure(state="disabled")
                        self.results_log.see("end")
                    self._results_log_seeded = True
            except tk.TclError:
                pass
        self.results_preview_btn.configure(state="normal" if self._has_local_previews_to_retry() else "disabled")

    def _has_local_previews_to_retry(self):
        """True when at least one known preview still exists locally."""
        base = getattr(self, "target_dir_current", "")
        if not base and hasattr(self, "path_var"):
            try:
                base = self.path_var.get()
            except Exception:
                base = ""
        records = list(getattr(self, "report_records", []) or [])
        if not records:
            manifest = getattr(self, "manifest", {}) or {}
            records = [dict(path=path, state=rec.get("state", ""))
                       for path, rec in manifest.get("files", {}).items()]
        for record in records:
            if record.get("state") != "preview":
                continue
            rel = record.get("path", "")
            if not rel or not base:
                continue
            normalized_rel = str(rel).replace("\\", os.sep)
            candidate = normalized_rel if os.path.isabs(normalized_rel) else os.path.join(base, normalized_rel)
            try:
                if os.path.isfile(candidate) and os.path.getsize(candidate) > 0:
                    return True
            except OSError:
                continue
        return False

    def _build_progress_sidebar(self, side, active):
        tk.Label(side, text="Ваш прогресс", bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 13, "bold")).grid(row=0, column=0, sticky="w", padx=15, pady=(15, 13))
        sidebar_steps = []
        items = [(1, "Ссылка на папку", "Скопируйте ссылки на общедоступные папки"), (2, "Cookie для скачивания", "Вставьте Cookie из вкладки Яндекс.Диска"), (3, "Папка сохранения", "Выберите место, куда будут загружены файлы")]
        for row_index, (num, title, desc) in enumerate(items, start=1):
            row = tk.Frame(side, bg=COLORS["surface"])
            row.grid(row=row_index, column=0, sticky="ew", padx=15, pady=(0, 13))
            bubble = tk.Label(row, text=str(num), bg="#E6EBF1", fg=COLORS["text"], font=(FONT, 10, "bold"), width=3, pady=4)
            bubble.pack(side="left", anchor="n", padx=(0, 9))
            text = tk.Frame(row, bg=COLORS["surface"])
            text.pack(side="left", fill="x", expand=True)
            tk.Label(text, text=title, bg=COLORS["surface"], fg=COLORS["text"], font=(FONT, 9, "bold")).pack(anchor="w")
            tk.Label(text, text=desc, bg=COLORS["surface"], fg=COLORS["muted"], font=(FONT, 8), wraplength=165, justify="left").pack(anchor="w", pady=(3, 0))
            sidebar_steps.append((bubble, num))
        side._sidebar_steps = sidebar_steps
        side._sidebar_active = active
        ttk.Separator(side).grid(row=4, column=0, sticky="ew", padx=15, pady=(0, 12))
        info = tk.Frame(side, bg=COLORS["surface_alt"], padx=10, pady=10)
        info.grid(row=5, column=0, sticky="ew", padx=12, pady=(0, 14))
        tk.Label(info, text="Зачем нужен Cookie?", bg=COLORS["surface_alt"], fg=COLORS["text"], font=(FONT, 9, "bold")).pack(anchor="w")
        tk.Label(info, text="Cookie помогает серверу подтвердить браузерную сессию и снизить вероятность блокировки запросов.", bg=COLORS["surface_alt"], fg=COLORS["muted"], font=(FONT, 8), wraplength=185, justify="left").pack(anchor="w", pady=(4, 0))
        side._step_state = active

    def _update_stepper(self, step):
        for index, (badge, title, line) in enumerate(self.stepper_nodes, start=1):
            if index < step:
                badge.configure(text="✓", bg=COLORS["accent"], fg="#FFFFFF")
                title.configure(fg=COLORS["muted"])
            elif index == step:
                badge.configure(text=str(index), bg=COLORS["accent"], fg="#FFFFFF")
                title.configure(fg=COLORS["accent"])
            else:
                badge.configure(text=str(index), bg="#E5EAF0", fg=COLORS["text"])
                title.configure(fg=COLORS["muted"])
            if line:
                line.configure(bg=COLORS["accent"] if index < step else COLORS["border"])

    def show_step(self, step):
        if self.is_downloading and step not in (3, "download"):
            return
        if step not in (1, 2, 3, "download", "results"):
            return

        # Each step is a separate page frame. Only the active page is mapped.
        for item in self.pages.values():
            item["page"].grid_remove()
        key = step if step in ("download", "results") else f"step{step}"
        self.pages[key]["page"].grid()
        self.current_page = key
        self.current_step = 3 if step in ("download", "results") else step
        self._update_stepper(self.current_step)

        side = self.pages[key]["side"]
        if key == "results":
            self._refresh_results_screen()
        if key == "results":
            side.grid()
            self.pages[key]["main"].grid_configure(columnspan=1, padx=(0, 12))
            self.pages[key]["page"].grid_columnconfigure(0, weight=1)
            self.pages[key]["page"].grid_columnconfigure(1, weight=0, minsize=220)
        else:
            self.pages[key]["main"].grid_configure(columnspan=1, padx=(0, 12))
        if key != "results" and not side.winfo_manager():
            side.grid()
        for bubble, number in getattr(side, "_sidebar_steps", []):
            if number < self.current_step:
                bubble.configure(text="✓", bg=COLORS["accent"], fg="#FFFFFF")
            elif number == self.current_step:
                bubble.configure(text=str(number), bg=COLORS["accent"], fg="#FFFFFF")
            else:
                bubble.configure(text=str(number), bg="#E6EBF1", fg=COLORS["text"])

        self.back_btn.pack_forget()
        self.reset_session_btn.pack_forget()
        self.next_btn.pack_forget()
        self.save_btn.pack_forget()
        self.footer_status.pack_forget()
        if hasattr(self, "back_to_download_btn"):
            self.back_to_download_btn.pack_forget()
        if hasattr(self, "launch_btn"):
            self.launch_btn.pack_forget()

        if step == 1:
            self.next_btn.configure(text="Далее: Cookie  →", command=self.go_next)
            self.next_btn.pack(side="left")
        elif step == 2:
            self.back_btn.configure(text="←  Назад", command=self.go_back, state="normal")
            self.back_btn.pack(side="left")
            self.next_btn.configure(text="Далее: Папка сохранения  →", command=self.go_next)
            self.next_btn.pack(side="left", padx=(12, 0))
        elif step == 3:
            self.back_btn.configure(text="←  Назад", command=self.go_back, state="normal")
            self.back_btn.pack(side="left")
            if self.has_completed_run:
                # After editing settings, offer BOTH actions: run with the new
                # settings (primary/red first) or return to previous results.
                self.next_btn.configure(text="К итогам скачивания  →", command=self.go_next)
                if self._step3_settings_changed():
                    self.launch_btn.configure(text="↓  Запустить скачивание", command=self.start_download_thread, style="Primary.TButton")
                    self.launch_btn.pack(side="left", padx=(12, 0))
                    self.next_btn.pack(side="left", padx=(12, 0))
                else:
                    self.next_btn.pack(side="left", padx=(12, 0))
            elif hasattr(self, "launch_btn"):
                self.launch_btn.configure(text="↓  Начать скачивание", command=self.start_download_thread, style="Primary.TButton")
                self.launch_btn.pack(side="left", padx=(12, 0))
        elif step == "results":
            # Results are the completed state of step 3. Back returns to
            # save-folder/options (step 3); Continue from that page returns here.
            self.back_btn.configure(text="←  Назад", command=self.go_back, state="normal")
            self.back_btn.pack(side="left")
            self.reset_session_btn.pack(side="left", padx=(10, 0))
        else:
            self.reset_session_btn.pack(side="left")
            # Download controls live on the download page; no wizard navigation here.

        if step not in ("download", "results"):
            self.footer_status.pack(side="left", padx=(4, 0))
        self._refresh_checklist()

        # Focus is moved only as part of explicit wizard navigation.
        # Never use focus_force() or a global FocusIn hook: those can steal
        # focus from buttons and other controls after Alt+Tab.
        if step in (1, 2):
            self.root.after_idle(lambda target_step=step: self._focus_step_field(target_step))

    def _focus_step_field(self, step):
        """Focus the primary editor for the active step, if it is actually visible."""
        widget = self.urls_text if step == 1 else self.cookies_text if step == 2 else None
        if widget is None:
            return
        try:
            if widget.winfo_exists() and widget.winfo_viewable():
                widget.focus_set()
                if step == 1:
                    widget.mark_set("insert", "end-1c")
                self._last_text_editor = widget
        except tk.TclError:
            pass

    def _focus_url_field(self):
        # Kept for the one-time startup focus scheduled after the root is mapped.
        self._focus_step_field(1)

    def _settings_signature(self):
        """Settings that affect the next download pass."""
        try:
            urls = tuple(self._urls()) if hasattr(self, "urls_text") else ()
            cookies = self.cookies_text.get("1.0", "end-1c").strip() if hasattr(self, "cookies_text") else ""
            path = os.path.normcase(os.path.abspath(os.path.expanduser(self.path_var.get().strip()))) if hasattr(self, "path_var") else ""
            mode = self.resume_mode_var.get() if hasattr(self, "resume_mode_var") else "resume"
            retry_previews = bool(self.retry_preview_var.get()) if hasattr(self, "retry_preview_var") else True
            return (urls, cookies, path, mode, retry_previews)
        except Exception:
            return None

    def _step3_settings_changed(self):
        baseline = getattr(self, "_completed_settings_signature", None)
        return bool(self.has_completed_run and baseline is not None and self._settings_signature() != baseline)

    def _update_step3_footer_action(self):
        """Update the primary footer action when settings change after completion."""
        if not hasattr(self, "launch_btn") or not hasattr(self, "next_btn"):
            return
        if self.current_page != "step3" or not self.has_completed_run or self.is_downloading:
            return
        # Keep the results action available at all times after a completed run.
        # If settings differ, show the red run action first and results second.
        self.next_btn.configure(text="К итогам скачивания  →", command=self.go_next)
        if self._step3_settings_changed():
            self.launch_btn.configure(text="↓  Запустить скачивание", command=self.start_download_thread, style="Primary.TButton")
            self.launch_btn.pack_forget()
            self.next_btn.pack_forget()
            self.launch_btn.pack(side="left", padx=(12, 0))
            self.next_btn.pack(side="left", padx=(12, 0))
        else:
            self.launch_btn.pack_forget()
            if not self.next_btn.winfo_manager():
                self.next_btn.pack(side="left", padx=(12, 0))

    def go_back(self):
        if self.current_page == "results":
            # Results are the completed view of step 3, so Back returns to the
            # save-folder/options page, not to Cookie.
            self.show_step(3)
        elif self.current_step == 2:
            self.show_step(1)
        elif self.current_step == 3 and not self.is_downloading and self.current_page not in ("download", "results"):
            self.show_step(2)

    def go_next(self):
        if self.current_step == 1:
            urls = self._urls()
            if not urls:
                messagebox.showwarning("Добавьте ссылку", "Сначала скопируйте ссылку на общедоступную папку Яндекс.Диска и вставьте её в поле.", parent=self.root)
                self.urls_text.focus_set()
                return
            invalid = [url for url in urls if not self._looks_like_yandex_url(url)]
            if invalid:
                messagebox.showwarning("Проверьте ссылку", "Одна из строк не похожа на ссылку Яндекс.Диска. Укажите полную ссылку вида https://disk.yandex.ru/d/…", parent=self.root)
                self.urls_text.focus_set()
                return
            self.show_step(2)
        elif self.current_step == 2:
            if not self.cookies_text.get("1.0", "end-1c").strip():
                messagebox.showwarning("Вставьте Cookie", "Скопируйте Cookie-строку из Cookie-Editor или DevTools и вставьте её в поле ниже.", parent=self.root)
                self.cookies_text.focus_set()
                return
            self.show_step(3)
        elif self.current_step == 3 and self.has_completed_run and not self.is_downloading:
            self.show_step("results")

    def _looks_like_yandex_url(self, url):
        try:
            parsed = urlparse(url.strip())
            return parsed.scheme in ("http", "https") and parsed.netloc.lower().endswith("yandex.ru") and len(parsed.path.strip("/").split("/")) >= 2
        except Exception:
            return False

    def _urls(self):
        return [line.strip() for line in self.urls_text.get("1.0", "end-1c").splitlines() if line.strip()]

    def _focus_debug(self, message):
        """Optional focus diagnostics; enabled with YADISK_DEBUG_FOCUS=1."""
        if os.environ.get("YADISK_DEBUG_FOCUS") != "1":
            return
        try:
            with (APP_DIR / "focus_debug.log").open("a", encoding="utf-8") as log_file:
                log_file.write(f"{time.strftime('%H:%M:%S')} | {message}\n")
        except OSError:
            pass

    def _focus_initial_field(self):
        """Focus the URL field once at startup; never steal focus on Alt+Tab."""
        self._focus_url_field()
        self._focus_debug("startup: focused URL field")

    def _enable_paste(self, widget):
        """Use the proven v1.2 clipboard handler; let Tk handle paste if clipboard_get fails."""
        def paste(_event=None):
            try:
                value = self.root.clipboard_get()
            except tk.TclError:
                return None  # Do not consume the event: Tk's native binding gets a chance.
            try:
                widget.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
            widget.insert("insert", value)
            widget.see("insert")
            self._refresh_checklist()
            self._schedule_autosave()
            return "break"

        def focus_field(_event=None):
            widget.after_idle(widget.focus_set)

        # Windows reports the physical V key as keycode 86 even when the
        # active keyboard layout changes its keysym (e.g. Russian layout: Cyrillic_em).
        def paste_by_physical_key(event):
            keysym = str(getattr(event, "keysym", "")).lower()
            keycode = getattr(event, "keycode", None)
            # Physical keycodes make Ctrl+A/C/V/X independent of keyboard layout.
            if keycode == 86 or keysym in ("v", "cyrillic_em"):
                return paste(event)
            if keycode == 65 or keysym in ("a", "ф"):
                widget.tag_add("sel", "1.0", "end-1c")
                widget.mark_set("insert", "end-1c")
                return "break"
            if keycode == 67 or keysym in ("c", "с"):
                try:
                    selected = widget.get("sel.first", "sel.last")
                    self.root.clipboard_clear()
                    self.root.clipboard_append(selected)
                    return "break"
                except tk.TclError:
                    return None
            if keycode == 88 or keysym in ("x", "ч"):
                try:
                    selected = widget.get("sel.first", "sel.last")
                    self.root.clipboard_clear()
                    self.root.clipboard_append(selected)
                    widget.delete("sel.first", "sel.last")
                    self._schedule_autosave()
                    return "break"
                except tk.TclError:
                    return None
            return None

        widget.bind("<Control-KeyPress>", paste_by_physical_key, add="+")
        widget.bind("<Control-v>", paste, add="+")
        widget.bind("<Control-V>", paste, add="+")
        widget.bind("<Shift-Insert>", paste, add="+")
        widget.bind("<<Paste>>", paste, add="+")
        widget.bind("<Button-1>", focus_field, add="+")
        widget.bind("<Button-3>", lambda event, w=widget: self._show_text_context_menu(event, w), add="+")

    def _enable_entry_paste(self, widget):
        """Reliable clipboard paste for ttk.Entry, including a Russian keyboard layout."""
        def paste(_event=None):
            try:
                value = self.root.clipboard_get()
            except tk.TclError:
                return None
            try:
                widget.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
            widget.insert("insert", value)
            widget.icursor("end")
            self._refresh_checklist()
            return "break"

        def physical_v(event):
            keysym = str(getattr(event, "keysym", "")).lower()
            keycode = getattr(event, "keycode", None)
            if keycode == 86 or keysym in ("v", "cyrillic_em"):
                return paste(event)
            if keycode == 65 or keysym in ("a", "ф"):
                widget.selection_range(0, "end")
                widget.icursor("end")
                return "break"
            if keycode == 67 or keysym in ("c", "с"):
                try:
                    self.root.clipboard_clear()
                    self.root.clipboard_append(widget.selection_get())
                    return "break"
                except tk.TclError:
                    return None
            if keycode == 88 or keysym in ("x", "ч"):
                try:
                    self.root.clipboard_clear()
                    self.root.clipboard_append(widget.selection_get())
                    widget.delete("sel.first", "sel.last")
                    return "break"
                except tk.TclError:
                    return None
            return None

        widget.bind("<Control-KeyPress>", physical_v, add="+")
        widget.bind("<Control-v>", paste, add="+")
        widget.bind("<Control-V>", paste, add="+")
        widget.bind("<Shift-Insert>", paste, add="+")
        widget.bind("<<Paste>>", paste, add="+")
        widget.bind("<Button-3>", lambda event, w=widget: self._show_entry_context_menu(event, w), add="+")

    def _show_entry_context_menu(self, event, widget):
        menu = tk.Menu(self.root, tearoff=0)
        menu.add_command(label="Вырезать", command=lambda: widget.event_generate("<<Cut>>"))
        menu.add_command(label="Копировать", command=lambda: widget.event_generate("<<Copy>>"))
        menu.add_command(label="Вставить", command=lambda: self._paste_into_entry(widget))
        menu.add_separator()
        menu.add_command(label="Выделить всё", command=lambda: (widget.select_range(0, "end"), widget.icursor("end")))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _paste_into_entry(self, widget):
        try:
            value = self.root.clipboard_get()
        except tk.TclError:
            widget.focus_set()
            widget.event_generate("<<Paste>>")
            return
        try:
            widget.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        widget.insert("insert", value)
        widget.icursor("end")
        self._refresh_checklist()

    def _add_tooltip(self, widget, text):
        """Small native Tk tooltip; does not steal focus or interfere with clicks."""
        state = {"after": None, "window": None}

        def hide(_event=None):
            if state["after"] is not None:
                try:
                    self.root.after_cancel(state["after"])
                except tk.TclError:
                    pass
                state["after"] = None
            if state["window"] is not None:
                try:
                    state["window"].destroy()
                except tk.TclError:
                    pass
                state["window"] = None

        def show():
            state["after"] = None
            if not widget.winfo_exists():
                return
            try:
                tip = tk.Toplevel(self.root)
                tip.wm_overrideredirect(True)
                tip.attributes("-topmost", True)
                label = tk.Label(tip, text=text, justify="left", wraplength=360,
                                 bg="#FFFBE6", fg="#344054", relief="solid", bd=1,
                                 padx=9, pady=6, font=(FONT, 9))
                label.pack()
                x = widget.winfo_rootx() + min(20, widget.winfo_width() // 3)
                y = widget.winfo_rooty() + widget.winfo_height() + 5
                tip.geometry(f"+{x}+{y}")
                state["window"] = tip
            except tk.TclError:
                state["window"] = None

        def schedule(_event=None):
            hide()
            state["after"] = self.root.after(550, show)

        widget.bind("<Enter>", schedule, add="+")
        widget.bind("<Leave>", hide, add="+")
        widget.bind("<ButtonPress>", hide, add="+")

    def _remember_editor(self, widget):
        self._last_text_editor = widget

    def _show_text_context_menu(self, event, widget):
        menu = tk.Menu(self.root, tearoff=0)
        menu.add_command(label="Вырезать", command=lambda: widget.event_generate("<<Cut>>"))
        menu.add_command(label="Копировать", command=lambda: widget.event_generate("<<Copy>>"))
        menu.add_command(label="Вставить", command=lambda: self._paste_into(widget))
        menu.add_separator()
        menu.add_command(label="Выделить всё", command=lambda: (widget.tag_add("sel", "1.0", "end-1c"), widget.mark_set("insert", "end-1c")))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _paste_into(self, widget):
        try:
            value = self.root.clipboard_get()
        except tk.TclError:
            widget.focus_set()
            widget.event_generate("<<Paste>>")
            return
        try:
            widget.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        widget.insert("insert", value)
        widget.see("insert")
        self._refresh_checklist()
        self._schedule_autosave()

    def toggle_manual_help(self):
        """Compatibility shim; manual help is now shown in the DevTools tab."""
        if hasattr(self, "cookie_method_tabs"):
            self.cookie_method_tabs.select(1)

    def _refresh_checklist(self):
        urls = self._urls() if hasattr(self, "urls_text") else []
        cookie = self.cookies_text.get("1.0", "end-1c").strip() if hasattr(self, "cookies_text") else ""
        path = self.path_var.get().strip() if hasattr(self, "path_var") else ""
        if hasattr(self, "review_urls"):
            self.review_urls.set(f"{len(urls)} ссылк(и)" if urls else "Не добавлены")
            self.review_cookie.set("Указан" if cookie else "Не указан")
            self.review_path.set(path or "Не выбрана")

    def _set_status(self, text, active=False):
        self.footer_status.configure(text="●  " + text, fg=COLORS["accent"] if active else COLORS["muted"])
        if hasattr(self, "download_status_var"):
            self.download_status_var.set(text)

    def _unique_path(self, target_dir, prefix, suffix):
        stamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        candidate = os.path.join(target_dir, f"{prefix}_{stamp}{suffix}")
        counter = 2
        while os.path.exists(candidate):
            candidate = os.path.join(target_dir, f"{prefix}_{stamp}_{counter}{suffix}")
            counter += 1
        return candidate

    def _load_manifest(self, target_dir):
        self.state_dir = os.path.join(target_dir, ".yadiskbackup")
        os.makedirs(self.state_dir, exist_ok=True)
        self.manifest_path = os.path.join(self.state_dir, "manifest.json")
        self.state_journal_path = os.path.join(self.state_dir, "state_events.jsonl")
        self.manifest = {"schema_version": 1, "updated_at": None, "files": {}}
        try:
            with open(self.manifest_path, "r", encoding="utf-8") as f:
                loaded = json.load(f)
            if isinstance(loaded, dict) and isinstance(loaded.get("files"), dict):
                self.manifest.update(loaded)
        except (OSError, ValueError, TypeError):
            pass
        # Replay events written after the last manifest checkpoint. Replaying the same
        # event twice is harmless because every event replaces one file's current state.
        try:
            with open(self.state_journal_path, "r", encoding="utf-8") as f:
                for line in f:
                    try:
                        event = json.loads(line)
                        rel = event.get("path")
                        record = event.get("record")
                        if rel and isinstance(record, dict):
                            self.manifest.setdefault("files", {})[rel] = record
                    except (ValueError, TypeError):
                        continue
        except OSError:
            pass
        self._manifest_dirty_count = 0

    def _save_manifest(self, force=False):
        if not self.manifest_path:
            return
        if not force and self._manifest_dirty_count < 25:
            return
        self.manifest["updated_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
        temp_path = self.manifest_path + ".tmp"
        try:
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(self.manifest, f, ensure_ascii=False, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_path, self.manifest_path)
            # Manifest now contains all current states, so the event journal can be
            # compacted safely. If a crash occurs before truncation, replay is idempotent.
            with open(self.state_journal_path, "w", encoding="utf-8") as f:
                f.flush()
            self._manifest_dirty_count = 0
        except OSError as exc:
            self._log(f"[!] Не удалось обновить внутренний манифест: {exc}")
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass

    def _set_manifest_record(self, path, state, reason="", size=0, actual_size=0, phase=""):
        record = {
            "state": state,
            "reason": str(reason or ""),
            "expected_size": max(0, int(size or 0)),
            "actual_size": max(0, int(actual_size or 0)),
            "attempts": 0,
            "last_attempt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "phase": phase or "",
        }
        previous = self.manifest.setdefault("files", {}).get(path, {})
        record["attempts"] = int(previous.get("attempts", 0)) + (1 if state in ("original", "preview", "failed") else 0)
        self.manifest["files"][path] = record
        self._manifest_dirty_count += 1
        try:
            with open(self.state_journal_path, "a", encoding="utf-8") as f:
                f.write(json.dumps({"path": path, "record": record}, ensure_ascii=False) + "\n")
                f.flush()
        except OSError as exc:
            self._log(f"[!] Не удалось записать состояние файла в журнал: {exc}")
        self._save_manifest(force=False)

    def _prepare_run_files(self, target_dir, migration_mode=False):
        """Create per-run reports and load or reset persistent download state."""
        self._load_manifest(target_dir)
        if migration_mode:
            # Migration from v2.3.14 must not use its manifest/journal as a resume cursor.
            self.manifest = {"schema_version": 1, "updated_at": None, "files": {}}
            self._manifest_dirty_count = 0
            for state_file in (self.manifest_path, self.state_journal_path):
                try:
                    with open(state_file, "w", encoding="utf-8") as state_stream:
                        state_stream.write("")
                except OSError as exc:
                    raise OSError(f"Не удалось сбросить старое состояние миграции ({state_file}): {exc}") from exc
        self.previous_run_summary = self.manifest.get("last_run_summary")
        self.previous_catalog_snapshot = self.manifest.get("last_catalog")
        self.current_catalog_delta = None
        # Keep user-facing reports and the live activity log out of the downloaded
        # files' root directory, but visible together in one dedicated folder.
        reports_dir = os.path.join(target_dir, "Журналы и отчёты")
        os.makedirs(reports_dir, exist_ok=True)
        self.reports_dir = reports_dir
        self.report_path = self._unique_path(reports_dir, "Отчёт_скачивания", ".txt")
        self.error_log_path = self._unique_path(reports_dir, "Отчёт_ошибок", ".txt")
        self.report_records = []
        self.run_errors = []
        stamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
        # Keep the live activity log visible beside the reports so the user can
        # inspect it during a pause or after stopping an incomplete run.
        self.live_log_path = self._unique_path(reports_dir, "Журнал_действий", ".log")
        with self._disk_log_lock:
            with open(self.live_log_path, "x", encoding="utf-8") as f:
                f.write(f"Журнал действий — начато {time.strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.flush()
        self._write_live_log(f"Внутреннее состояние: {self.manifest_path}")
        # Reports exist from the beginning and are refreshed while the run is active.
        self._write_report("Скачивание выполняется")
        self._write_error_report()

    def _write_live_log(self, message):
        path = getattr(self, "live_log_path", None)
        if not path:
            return
        stamp = time.strftime("[%H:%M:%S]")
        try:
            with self._disk_log_lock:
                with open(path, "a", encoding="utf-8") as f:
                    for line in str(message).splitlines() or [""]:
                        f.write(f"{stamp} {line}\n")
                    f.flush()
        except OSError:
            pass

    def _write_report(self, status="Скачивание выполняется"):
        path = getattr(self, "report_path", None)
        if not path:
            return
        records = list(getattr(self, "report_records", []))
        original = [r for r in records if r.get("state") == "original"]
        preview = [r for r in records if r.get("state") == "preview"]
        failed = [r for r in records if r.get("state") == "failed"]
        unprocessed = [r for r in records if r.get("state") == "unprocessed"]
        unknown = [r for r in records if r.get("state") == "unknown"]
        total_count = len(records)
        total_size = sum(max(0, int(r.get("size", 0) or 0)) for r in records)
        original_size = sum(max(0, int(r.get("actual_size", 0) or r.get("size", 0) or 0)) for r in original)
        preview_size = sum(max(0, int(r.get("actual_size", 0) or 0)) for r in preview)
        failed_size = sum(max(0, int(r.get("size", 0) or 0)) for r in failed)
        lines = [
            "ИТОГИ СКАЧИВАНИЯ", f"Дата: {time.strftime('%Y-%m-%d %H:%M:%S')}",
            f"Состояние: {status}", "",
            f"Всего файлов найдено: {total_count}",
            f"Общий размер по данным Яндекс.Диска: {self._human_size(total_size)}",
            f"Скачано оригиналов: {len(original)} ({self._human_size(original_size)})",
            f"Скачано превью: {len(preview)} ({self._human_size(preview_size)})",
            f"Не удалось скачать: {len(failed)} ({self._human_size(failed_size)} — ожидаемый размер по данным Яндекс.Диска)",
            f"Не обработано: {len(unprocessed)}",
            f"Уже были в папке, тип не удалось определить: {len(unknown)}", "",
            "Ссылки ниже ведут в папку на Яндекс.Диске, а не на сам файл.",
            "Откройте папку, чтобы посмотреть файл и определить, что именно не удалось скачать.",
            "",
            "ОШИБКИ — подробности также в отдельном отчёте об ошибках",
        ]
        lines.extend(self._grouped_report_lines(
            failed, "[ОШИБКА]",
            lambda r: f" — {r.get('reason') or 'Причина не указана'}"))
        lines.extend(["", "НЕТ ОРИГИНАЛА, НО ЕСТЬ ПРЕВЬЮ"])
        lines.extend(self._grouped_report_lines(
            preview, "[ЕСТЬ ПРЕВЬЮ]",
            lambda r: f" ({self._human_size(r.get('actual_size', 0))})"))

        # A file belongs in the "nothing downloaded" section only when neither
        # an original nor a preview exists locally. Failed and not-yet-processed
        # records are checked against disk to avoid misleading the user.
        no_local_file = [r for r in failed + unprocessed if not self._report_local_file_exists(r)]
        lines.extend(["", "НЕТ НИ ОРИГИНАЛА, НИ ПРЕВЬЮ"])
        lines.extend(self._grouped_report_lines(
            no_local_file, "[НЕТ ФАЙЛА]",
            lambda r: f" — {r.get('reason') or ('ещё не обработан' if r.get('state') == 'unprocessed' else 'скачивание не удалось')}"))

        if unprocessed:
            lines.extend(["", "НЕ ОБРАБОТАНЫ (ОЖИДАЮТ ПОПЫТКИ)"])
            lines.extend(self._grouped_report_lines(unprocessed, "[ОЖИДАЕТ]"))
        lines.extend(["", "УЖЕ БЫЛИ В ПАПКЕ, ТИП НЕ УДАЛОСЬ ОПРЕДЕЛИТЬ"])
        lines.extend(self._grouped_report_lines(unknown, "[НЕИЗВЕСТНО]"))
        lines.extend(["", "Если оригиналы пока доступны не для всех файлов, можно повторить проверку позже.",
                      "Если программа оказалась полезной: https://donatty.com/yandexbackup"])
        try:
            temp = path + ".tmp"
            with self._disk_log_lock:
                with open(temp, "w", encoding="utf-8") as f:
                    f.write("\n".join(lines) + "\n")
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(temp, path)
        except OSError as exc:
            self._log(f"[!] Не удалось обновить итоговый отчёт: {exc}")

    def _report_local_file_exists(self, record):
        """Return whether the report entry has any local file (original or preview)."""
        rel = str(record.get("path", "") or "")
        candidates = []
        for base in (getattr(self, "target_dir_current", None),
                     getattr(self, "path_var", None).get().strip() if getattr(self, "path_var", None) else None):
            if base:
                candidates.append(os.path.join(base, rel.replace("\\", os.sep).replace("/", os.sep)))
        for candidate in candidates:
            try:
                if os.path.isfile(candidate) and os.path.getsize(candidate) > 0:
                    return True
            except OSError:
                pass
        return False

    def _record_folder_url(self, record):
        path = record.get("path", "")
        return (record.get("folder_url") or
                getattr(self, "source_folder_links", {}).get(path, ""))

    def _grouped_report_lines(self, records, label, suffix_builder=None):
        """Render report entries grouped by their containing Yandex Disk folder."""
        groups = {}
        order = []
        for record in records:
            path = record.get("path", "Файл")
            folder_url = self._record_folder_url(record)
            parent = os.path.dirname(str(path).replace("\\", "/"))
            key = folder_url or parent or "__unknown__"
            if key not in groups:
                groups[key] = {"url": folder_url, "parent": parent, "records": []}
                order.append(key)
            groups[key]["records"].append(record)

        lines = []
        for key in order:
            group = groups[key]
            if lines:
                lines.append("")
            if group["url"]:
                # Keep folder URLs readable in TXT reports. Browsers accept
                # Unicode paths and automatically encode spaces when pasted.
                readable_url = unquote(group["url"])
                lines.append(f"Папка на Яндекс.Диске: {readable_url}")
            elif group["parent"]:
                lines.append(f"Папка: {group['parent'].rstrip('/')}/")
            else:
                lines.append("Папка на Яндекс.Диске: ссылка не определена автоматически")
            for record in group["records"]:
                suffix = suffix_builder(record) if suffix_builder else ""
                lines.append(f"{label} {record.get('path', 'Файл')}{suffix}")
        return lines

    def _report_record_lines(self, label, record, suffix=""):
        """Render a single record (used for standalone discovery errors)."""
        return self._grouped_report_lines([record], label, lambda _r: suffix)

    def _write_error_report(self):
        """Create the user-facing error report only after work has finished.

        It is a new file for each run, so opening an older report never blocks
        the downloader from writing the current result.
        """
        path = getattr(self, "error_log_path", None)
        if not path:
            return
        errors = []
        seen = set()
        for item in getattr(self, "run_errors", []):
            key = (item.get("path", ""), item.get("reason", ""))
            if key not in seen:
                seen.add(key)
                errors.append(item)
        for record in getattr(self, "report_records", []):
            if record.get("state") == "failed":
                item = {"path": record.get("path", ""), "reason": record.get("reason") or "Неизвестная ошибка",
                        "folder_url": record.get("folder_url", "")}
                key = (item["path"], item["reason"])
                if key not in seen:
                    seen.add(key)
                    errors.append(item)
        for item in errors:
            if not item.get("folder_url"):
                item["folder_url"] = getattr(self, "source_folder_links", {}).get(item.get("path", ""), "")
        lines = ["ОТЧЁТ ОБ ОШИБКАХ СКАЧИВАНИЯ", f"Дата: {time.strftime('%Y-%m-%d %H:%M:%S')}", ""]
        if errors:
            lines.append(f"Ошибок/проблем: {len(errors)}")
            lines.extend(self._grouped_report_lines(
                errors, "[ОШИБКА]", lambda item: f" — {item.get('reason') or 'Причина не указана'}"))
        else:
            lines.append("Ошибок скачивания не зарегистрировано.")
        try:
            temp = path + ".tmp"
            with self._disk_log_lock:
                with open(temp, "w", encoding="utf-8") as f:
                    f.write("\n".join(lines) + "\n")
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(temp, path)
        except OSError as exc:
            self._log(f"[!] Не удалось создать отчёт об ошибках: {exc}")

    def _record_result(self, path, state, reason="", size=0, actual_size=0, phase=""):
        record = {"path": path, "state": state, "reason": reason or "", "size": int(size or 0),
                  "actual_size": int(actual_size or 0), "phase": phase or "",
                  "folder_url": getattr(self, "source_folder_links", {}).get(path, "")}
        for index, existing in enumerate(self.report_records):
            if existing["path"] == path:
                self.report_records[index] = record
                break
        else:
            self.report_records.append(record)
        self._set_manifest_record(path, state, reason, size, actual_size, phase)

    def _open_report(self, path):
        if not path or not os.path.isfile(path):
            messagebox.showwarning("Отчёт пока недоступен", "Файл отчёта ещё не создан.", parent=self.root)
            return
        try:
            if sys.platform == "win32":
                os.startfile(path)
            elif sys.platform == "darwin":
                subprocess.Popen(["open", path])
            else:
                subprocess.Popen(["xdg-open", path])
        except Exception as exc:
            messagebox.showerror("Не удалось открыть отчёт", f"Откройте файл вручную:\n{path}\n\n{exc}", parent=self.root)

    def _normalize_log_message(self, message):
        text = str(message)
        # Replace compact glyph-only markers with explicit labels that remain clear
        # in the UI, saved journal, and copied reports on every platform/font.
        replacements = [
            ("[!!!]", "[КРИТИЧЕСКАЯ ОШИБКА]"), ("[✖]", "[ОШИБКА]"),
            ("[!]", "[ПРЕДУПРЕЖДЕНИЕ]"), ("[✓]", "[ОК]"),
            ("[↓]", "[ЗАГРУЗКА]"), ("[i]", "[ИНФО]"),
            ("[*]", "[ПРОВЕРКА]"), ("[+]", "[ПАПКА]"),
            ("[Ⅱ]", "[ПАУЗА]"), ("[▶]", "[ВОЗОБНОВЛЕНИЕ]"),
            ("[↻]", "[ПОВТОР]"),
        ]
        for old, new in replacements:
            text = text.replace(old, new)
        return text

    def _log(self, message):
        readable = self._normalize_log_message(message)
        self._write_live_log(readable)
        self.log_queue.put(("log", readable))

    def _poll_log_queue(self):
        try:
            while True:
                kind, payload = self.log_queue.get_nowait()
                if kind == "log":
                    self._append_log(payload)
                elif kind == "status":
                    text, active = payload
                    self._set_status(text, active)
                elif kind == "progress_init":
                    self.total_files, self.total_bytes, self.catalog_file_count, self.catalog_bytes = payload
                    self.processed_files = 0
                    self.processed_bytes = 0
                    self.downloaded_bytes_run = 0
                    self.transfer_seconds_run = 0.0
                    self.current_file_bytes = 0
                    self.progress_done_expected_bytes = 0
                    self._last_metrics_update = 0.0
                    self._update_progress_ui()
                elif kind == "phase":
                    self._set_status(payload, True)
                elif kind == "file_attempt_start":
                    self.current_file_bytes = 0
                    self.last_chunk_bytes = 0
                elif kind == "transfer_time":
                    self.transfer_seconds_run += max(0.0, float(payload or 0))
                elif kind == "file_existing":
                    name, size, state = payload
                    self.recent_files.insert(0, {"name": name, "size": size, "state": state, "percent": 100})
                    self.recent_files = self.recent_files[:6]
                    self._render_recent_files()
                elif kind == "file_start":
                    name, size, index = payload
                    self.current_file_name = name
                    self.current_file_size = max(0, int(size or 0))
                    self.current_file_bytes = 0
                    self.last_chunk_bytes = 0
                    self.current_index = index
                    self.current_file_var.set(name)
                    self.file_percent_var.set("0%" if self.current_file_size else "—")
                    self.file_detail_var.set(self._human_size(0) + (f" из {self._human_size(self.current_file_size)}" if self.current_file_size else ""))
                    self.file_progress["value"] = 0
                    self.recent_files.insert(0, {"name": name, "size": size, "state": "Скачивается…", "percent": 0})
                    self.recent_files = self.recent_files[:6]
                    self._render_recent_files()
                elif kind == "file_chunk":
                    current_bytes, size = payload
                    self.current_file_bytes = current_bytes
                    self.downloaded_bytes_run += max(0, current_bytes - getattr(self, "last_chunk_bytes", 0))
                    self.last_chunk_bytes = current_bytes
                    self.current_file_size = max(size or 0, 0)
                    pct = (current_bytes / size * 100) if size else 0
                    self.file_progress["value"] = pct
                    self.file_percent_var.set(f"{pct:.0f}%" if size else self._human_size(current_bytes))
                    self.file_detail_var.set(self._human_size(current_bytes) + (f" из {self._human_size(size)}" if size else ""))
                    if self.recent_files:
                        self.recent_files[0]["percent"] = pct
                    self._update_progress_ui()
                    self._render_recent_files()
                elif kind == "file_done":
                    name, size, state = payload
                    self.processed_files += 1
                    self.processed_bytes += max(int(size or 0), 0)
                    completed_states = {
                        "Оригинал скачан", "Оригинал уже есть", "Скачано превью",
                        "Превью уже есть", "Превью сохранено", "Файл уже есть",
                        "Файл уже есть — тип не определён", "Локальный файл сохранён",
                        "Загружен", "Уже есть", "Пропущен",
                    }
                    if state in completed_states:
                        self.file_progress["value"] = 100
                        self.file_percent_var.set("100%")
                    # The task's expected size was added to completed work by the
                    # worker before this event. Clear live bytes to avoid counting
                    # the same file twice in the overall progress display.
                    self.current_file_bytes = 0
                    self.last_chunk_bytes = 0
                    if self.recent_files:
                        self.recent_files[0].update({"name": name, "size": size, "state": state, "percent": 100 if state in completed_states else 0})
                    self._update_progress_ui()
                    self._render_recent_files()
                elif kind == "dialog":
                    title, text, is_error = payload
                    if is_error:
                        messagebox.showerror(title, text, parent=self.root)
                    else:
                        messagebox.showinfo(title, text, parent=self.root)
                elif kind == "finished":
                    self.is_downloading = False
                    self.is_paused = False
                    self.has_completed_run = self.status_result != "Перезапуск…"
                    if self.has_completed_run:
                        self._completed_settings_signature = self._settings_signature()
                    self.pause_event.clear()
                    self.pause_btn.configure(state="disabled", text=("↻  Повторить скачивание" if self.status_result in ("Ошибка скачивания", "Остановлено", "Завершено с ошибками", "Файлы не найдены") else "✓  Скачивание завершено"), command=self.start_download_thread)
                    self.stop_download_btn.configure(state="disabled")
                    self.stop_download_btn.pack_forget()
                    if self.status_result in ("Скачивание завершено",):
                        self.pause_btn.configure(state="disabled")
                    self.download_restart_btn.pack_forget()
                    self.download_restart_btn.configure(state="normal")
                    self._set_status("Загрузка завершена" if self.status_result in ("success", "Скачивание завершено") else self.status_result, False)
                    if getattr(self, "report_path", None) and os.path.isfile(self.report_path):
                        self.report_link.configure(text="Открыть итоговый отчёт ↗")
                        if not self.report_link.winfo_manager():
                            self.report_link.pack(side="left", padx=(0, 12))
                    if getattr(self, "error_log_path", None) and os.path.isfile(self.error_log_path):
                        self.error_report_link.configure(text="Отчёт об ошибках ↗")
                        if not self.error_report_link.winfo_manager():
                            self.error_report_link.pack(side="left", padx=(0, 12))
                    previews_remain = any(r.get("state") == "preview" for r in getattr(self, "report_records", []))
                    if not self.open_folder_btn.winfo_manager():
                        self.open_folder_btn.pack(side="left", padx=(10, 12))
                    if previews_remain:
                        if not self.retry_preview_final_btn.winfo_manager():
                            self.retry_preview_final_btn.pack(side="left", padx=(0, 0))
                        self.retry_preview_help.pack(fill="x", padx=18, pady=(0, 12))
                    else:
                        self.retry_preview_final_btn.pack_forget()
                        self.retry_preview_help.pack_forget()
                    self.reset_session_btn.pack_forget()
                    if self.restart_requested:
                        self.restart_requested = False
                        self.root.after(300, self.start_download_thread)
                    elif self.status_result != "Перезапуск…":
                        # A user-requested stop is also a finished partial run:
                        # show its snapshot/results instead of leaving the user on
                        # a frozen progress screen.
                        self.root.after(180, self._show_results_after_finish)
        except queue.Empty:
            pass
        if self.is_downloading and time.time() - self._last_metrics_update >= 1.0:
            self._last_metrics_update = time.time()
            self._update_progress_ui()
        self.root.after(100, self._poll_log_queue)

    def _show_results_after_finish(self):
        """Show the results screen after stop/completion and restore its footer navigation."""
        # The worker may still be unwinding when the finished event is handled.
        if self.is_downloading:
            self.root.after(100, self._show_results_after_finish)
            return
        self.show_step("results")
        # Keep the bottom navigation available even if another completion path
        # hid the reset button while the download screen was active.
        try:
            if not self.reset_session_btn.winfo_manager():
                self.reset_session_btn.pack(side="left", padx=(10, 0))
            self.reset_session_btn.configure(state="normal")
            self.root.update_idletasks()
        except (tk.TclError, AttributeError):
            pass

    def _append_log(self, message):
        stamp = time.strftime("%H:%M:%S")
        lines = str(message).splitlines() or [""]
        for widget_name in ("log_text", "results_log"):
            widget = getattr(self, widget_name, None)
            if widget is None:
                continue
            try:
                widget.configure(state="normal")
                for line in lines:
                    low = line.lower()
                    if "[критическая ошибка]" in low or "[ошибка]" in low or "не удалось" in low or "не скачалось" in low:
                        tag = "log_error"
                    elif "[предупреждение]" in low or "предупреждение" in low:
                        tag = "log_warning"
                    elif "[ок]" in low or "все задачи обработаны" in low or "скачан оригинал получен" in low:
                        tag = "log_ok"
                    elif "[загрузка]" in low or "скачиваю" in low:
                        tag = "log_download"
                    elif "[инфо]" in low or "[проверка]" in low or "[папка]" in low:
                        tag = "log_info"
                    else:
                        tag = "log_default"
                    start = widget.index("end-1c")
                    widget.insert("end", f"[{stamp}]  {line}\n")
                    widget.tag_add(tag, start, "end-1c")
                widget.see("end")
                widget.configure(state="disabled")
            except tk.TclError:
                pass

    def _human_size(self, value):
        value = float(value or 0)
        units = ["Б", "КБ", "МБ", "ГБ", "ТБ"]
        for unit in units:
            if value < 1024 or unit == units[-1]:
                return f"{value:.1f} {unit}" if unit != "Б" else f"{int(value)} Б"
            value /= 1024

    def _update_progress_ui(self):
        total = max(1, self.total_files)
        done_pct = 100.0 if self.total_files == 0 else min(100, (self.processed_files / total) * 100)
        if hasattr(self, "overall_progress"):
            self.overall_progress["value"] = done_pct
            self.overall_percent_var.set(f"{done_pct:.0f}%")
            self.overall_count_var.set("Нет задач для скачивания" if self.total_files == 0 else f"Обработано: {self.processed_files} из {self.total_files} задач")
            # Checked progress is measured against the entire remote catalogue,
            # not only tasks that require downloading. Downloaded bytes stay separate.
            target_bytes = max(0, int(getattr(self, "catalog_bytes", 0) or 0))
            completed_expected = max(0, int(getattr(self, "progress_done_expected_bytes", 0) or 0))
            current_expected = max(0, int(getattr(self, "current_file_size", 0) or 0))
            current_live = max(0, int(getattr(self, "current_file_bytes", 0) or 0))
            current_live = min(current_live, current_expected) if current_expected else current_live
            progress_bytes_done = min(target_bytes, completed_expected + current_live)
            actual_downloaded = max(0, int(self.downloaded_bytes_run))
            self.overall_bytes_var.set(f"Скачано: {self._human_size(actual_downloaded)}")
            self.overall_checked_var.set(f"Проверено: {self._human_size(progress_bytes_done)} из {self._human_size(target_bytes)}")
            now = time.time()
            paused = self.paused_total_seconds
            if self.is_paused and self.pause_started_at:
                paused += max(0, now - self.pause_started_at)
            elapsed = max(0, int(round(now - (self.download_started_at or now) - paused)))
            if elapsed >= 1:
                self.elapsed_var.set(self._format_eta(elapsed).replace("около ", ""))
            transfer_seconds = max(0.0, self.transfer_seconds_run)
            speed_bps = actual_downloaded / transfer_seconds if transfer_seconds > 0 else 0.0
            self.speed_var.set(f"{self._human_size(speed_bps * 3600)}/ч" if speed_bps > 0 else "рассчитывается…")
            remaining_tasks = max(0, self.total_files - self.processed_files)
            # Predict remaining time by task count, independent of network speed.
            eta = remaining_tasks * 20
            self.eta_var.set(self._format_eta(int(eta)) if eta > 0 else "завершение…")
            self.side_download_count_var.set("Все файлы уже обработаны" if self.total_files == 0 else f"{self.processed_files} из {self.total_files} задач ({done_pct:.0f}%)")

    def _format_eta(self, seconds):
        if seconds < 60:
            return f"около {seconds} сек."
        mins = seconds // 60
        return f"около {mins} мин." if mins < 60 else f"около {mins // 60} ч. {mins % 60} мин."

    def _configure_log_tags(self, widget):
        """High-contrast, explicit status colors for the activity journal."""
        widget.tag_configure("log_error", foreground="#B42318", font=(MONO, 8, "bold"), background="#FFF0EE")
        widget.tag_configure("log_warning", foreground="#9A6700", font=(MONO, 8, "bold"), background="#FFF7DB")
        widget.tag_configure("log_ok", foreground="#067647", font=(MONO, 8, "bold"), background="#EAF8F0")
        widget.tag_configure("log_download", foreground="#175CD3", font=(MONO, 8, "bold"))
        widget.tag_configure("log_info", foreground="#475467")
        widget.tag_configure("log_default", foreground="#344054")

    def _build_download_screen(self):
        main, side = self._new_page("download")
        # The download page has its own vertical scroll area so the journal is always reachable.
        scroll_host = tk.Frame(main, bg=COLORS["bg"])
        scroll_host.pack(fill="both", expand=True)
        content_canvas = tk.Canvas(scroll_host, bg=COLORS["bg"], highlightthickness=0, bd=0)
        self.download_content_canvas = content_canvas
        content_scroll = ttk.Scrollbar(scroll_host, orient="vertical", command=content_canvas.yview, style="Slim.Vertical.TScrollbar")
        content_canvas.configure(yscrollcommand=content_scroll.set)
        content_scroll.pack(side="right", fill="y")
        content_canvas.pack(side="left", fill="both", expand=True)
        content = tk.Frame(content_canvas, bg=COLORS["bg"])
        content_window = content_canvas.create_window((0, 0), window=content, anchor="nw")
        def update_download_scrollregion(_event=None):
            # Updating labels/cards during download changes the content height.
            # Keep the user's current viewport instead of snapping to the top.
            try:
                current_view = content_canvas.yview()
                content_canvas.configure(scrollregion=content_canvas.bbox("all"))
                if current_view and current_view[0] > 0:
                    content_canvas.yview_moveto(current_view[0])
            except tk.TclError:
                pass

        content.bind("<Configure>", update_download_scrollregion)
        content_canvas.bind("<Configure>", lambda e: content_canvas.itemconfigure(content_window, width=e.width))
        # Bind globally so wheel events work over the entire page, not only on
        # the narrow canvas/scrollbar edge. _on_mousewheel routes by pointer.
        self.root.bind_all("<MouseWheel>", self._on_mousewheel, add="+")
        self.root.bind_all("<Button-4>", self._on_mousewheel, add="+")
        self.root.bind_all("<Button-5>", self._on_mousewheel, add="+")
        main = content
        current = self._card(main)
