        self.download_status_var = tk.StringVar(value="Подготовка к скачиванию")
        tk.Label(current, textvariable=self.download_status_var, bg=COLORS["surface"], fg=COLORS["muted"], font=(FONT, 9)).pack(anchor="w", padx=16, pady=(0, 10))

